"use client";

export { useAutocompleteQuery } from "./use-autocomplete-query";
export { useAutocompleteInfiniteQuery } from "./use-autocomplete-infinite-query";
export type {
  AutocompleteQueryBinding,
  AutocompleteQueryStateOptions,
} from "./autocomplete-query-types";

import type { ReactNode } from "react";

import type {
  AutocompleteCommonProps,
  AutocompleteMode,
} from "./autocomplete-types";

export interface AutocompleteQueryStateOptions {
  search?: string;
  defaultSearch?: string;
  onSearchChange?: (search: string) => void;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  enabled?: boolean;
  debounceMs?: number;
  minSearchLength?: number;
  hintMessage?: ReactNode;
}

export type AutocompleteQueryBinding<
  Item,
  Mode extends AutocompleteMode,
  Multiple extends boolean,
> = Pick<
  AutocompleteCommonProps<Item>,
  "items" | "filter" | "open" | "onOpenChange" | "loading" | "error"
> & {
  mode: Mode;
  multiple: Multiple;
} & (Mode extends "free-text"
    ? Multiple extends false
      ? {
          value: string;
          onValueChange: (value: string) => void;
          inputValue?: never;
          onInputValueChange?: never;
        }
      : { inputValue: string; onInputValueChange: (value: string) => void }
    : { inputValue: string; onInputValueChange: (value: string) => void });

export const validateAutocompleteQueryConfiguration = (
  debounceMs: number,
  minSearchLength: number
) => {
  if (
    !Number.isFinite(debounceMs) ||
    debounceMs < 0 ||
    debounceMs > 2_147_483_647 ||
    !Number.isSafeInteger(minSearchLength) ||
    minSearchLength < 0
  ) {
    throw new RangeError(
      "Invalid autocomplete debounce or minimum search length"
    );
  }
};

export const isAutocompleteQueryEligible = ({
  open,
  search,
  debouncedSearch,
  minSearchLength,
  enabled,
}: {
  open: boolean;
  search: string;
  debouncedSearch: string;
  minSearchLength: number;
  enabled: boolean;
}) =>
  open &&
  enabled &&
  search.length >= minSearchLength &&
  search === debouncedSearch;

export const dedupeAutocompleteItems = <Item>(
  items: readonly Item[],
  getItemValue: (item: Item) => string
): Item[] => {
  const seen = new Set<string>();
  return items.filter((item) => {
    const id = getItemValue(item);
    if (seen.has(id)) {
      return false;
    }
    seen.add(id);
    return true;
  });
};

"use client";

import { useEffect, useState } from "react";

import {
  isAutocompleteQueryEligible,
  validateAutocompleteQueryConfiguration,
} from "./autocomplete-query-state";
import type { AutocompleteQueryStateOptions } from "./autocomplete-query-types";

export const useAutocompleteQueryState = (
  options: AutocompleteQueryStateOptions
) => {
  const { debounceMs = 300, minSearchLength = 0 } = options;
  validateAutocompleteQueryConfiguration(debounceMs, minSearchLength);
  const [localSearch, updateSearch] = useState(options.defaultSearch ?? "");
  const [localOpen, updateOpen] = useState(options.defaultOpen ?? false);
  const search = options.search ?? localSearch;
  const open = options.open ?? localOpen;
  const [settled, settle] = useState(search);
  useEffect(() => {
    const timer = setTimeout(() => settle(search), debounceMs);
    return () => clearTimeout(timer);
  }, [search, debounceMs]);
  const debouncedSearch = debounceMs === 0 ? search : settled;
  const setSearch = (next: string) => {
    if (options.search === undefined) {
      updateSearch(next);
    }
    if (search !== next) {
      options.onSearchChange?.(next);
    }
  };
  const setOpen = (next: boolean) => {
    if (options.open === undefined) {
      updateOpen(next);
    }
    if (open !== next) {
      options.onOpenChange?.(next);
    }
  };
  return {
    debouncedSearch,
    eligible: isAutocompleteQueryEligible({
      open,
      search,
      debouncedSearch,
      minSearchLength,
      enabled: options.enabled !== false,
    }),
    belowMinimum: search.length < minSearchLength,
    hintMessage:
      options.hintMessage ?? `Enter at least ${minSearchLength} characters.`,
    open,
    search,
    setOpen,
    setSearch,
  };
};

"use client";

import { skipToken, useQuery } from "@tanstack/react-query";
import type { QueryKey, UseQueryOptions } from "@tanstack/react-query";
import type { ReactNode } from "react";

import type {
  AutocompleteQueryBinding,
  AutocompleteQueryStateOptions,
} from "./autocomplete-query-types";
import type { AutocompleteMode } from "./autocomplete-types";
import { useAutocompleteQueryState } from "./use-autocomplete-query-state";

export type AutocompleteQuerySelected<Options> = Options extends {
  select?: (data: never) => infer Selected;
}
  ? Selected
  : Options extends { queryFn?: (context: never) => infer Raw }
    ? Awaited<Raw>
    : never;

export const useAutocompleteQuery = <
  Raw,
  Item,
  Data = Raw,
  ErrorType = Error,
  Key extends QueryKey = QueryKey,
  Mode extends AutocompleteMode = "free-text",
  Multiple extends boolean = false,
>(
  options: AutocompleteQueryStateOptions & {
    mode?: Mode;
    multiple?: Multiple;
    queryOptions: (input: {
      search: string;
    }) => UseQueryOptions<Raw, ErrorType, Data, Key>;
    getItems: (data: Data) => readonly Item[];
    formatError?: (error: ErrorType) => ReactNode;
  }
) => {
  const state = useAutocompleteQueryState(options);
  // Native options cross a single generic adapter boundary; Query evaluates enabled
  // against its real Query object, not a fabricated policy object.
  const native = options.queryOptions({ search: state.debouncedSearch });
  const nativeEnabled = native.enabled;
  const enabled: typeof native.enabled = (query) =>
    state.eligible &&
    native.queryFn !== skipToken &&
    (typeof nativeEnabled === "function"
      ? nativeEnabled(query)
      : nativeEnabled !== false);
  const query = useQuery({ ...native, enabled });
  const allowed = state.eligible && query.isEnabled;
  const waiting =
    state.open && !state.belowMinimum && state.search !== state.debouncedSearch;
  const usable =
    state.search === state.debouncedSearch &&
    !state.belowMinimum &&
    !query.isPlaceholderData;
  const items =
    usable && query.data !== undefined ? options.getItems(query.data) : [];
  const binding = {
    mode: options.mode ?? "free-text",
    multiple: options.multiple ?? false,
    items,
    filter: null,
    open: state.open,
    onOpenChange: state.setOpen,
    ...(options.mode !== "selection" && !options.multiple
      ? { value: state.search, onValueChange: state.setSearch }
      : { inputValue: state.search, onInputValueChange: state.setSearch }),
    hintMessage: state.belowMinimum ? state.hintMessage : undefined,
    loading:
      waiting ||
      (allowed &&
        query.isFetching &&
        (query.data === undefined || query.isPlaceholderData)),
    backgroundLoading: usable && query.data !== undefined && query.isFetching,
    error:
      usable && query.data === undefined && query.error
        ? (options.formatError?.(query.error) ?? "Could not load suggestions.")
        : undefined,
    onRetry: () => {
      if (allowed) {
        return query.refetch();
      }
    },
  };
  return {
    query,
    search: state.search,
    open: state.open,
    setSearch: state.setSearch,
    setOpen: state.setOpen,
    autocompleteProps: binding as unknown as AutocompleteQueryBinding<
      Item,
      Mode,
      Multiple
    > &
      Pick<typeof binding, "hintMessage" | "backgroundLoading" | "onRetry">,
  };
};

"use client";

import { hashKey, skipToken, useInfiniteQuery } from "@tanstack/react-query";
import type {
  InfiniteData,
  QueryKey,
  UseInfiniteQueryOptions,
} from "@tanstack/react-query";
import { useRef } from "react";
import type { ReactNode } from "react";

import { dedupeAutocompleteItems } from "./autocomplete-query-state";
import type {
  AutocompleteQueryBinding,
  AutocompleteQueryStateOptions,
} from "./autocomplete-query-types";
import type {
  AutocompleteMode,
  AutocompletePaginationProps,
} from "./autocomplete-types";
import type { AutocompleteQuerySelected } from "./use-autocomplete-query";
import { useAutocompleteQueryState } from "./use-autocomplete-query-state";

type SelectedInfinite<F> = F extends { select?: (data: never) => infer Data }
  ? Data
  : InfiniteData<AutocompleteQuerySelected<F>>;
type SelectedPage<Data> = Data extends { pages: (infer Page)[] } ? Page : never;

export const useAutocompleteInfiniteQuery = <
  RawPage,
  Item,
  Page = RawPage,
  ErrorType = Error,
  Key extends QueryKey = QueryKey,
  Param = unknown,
  Mode extends AutocompleteMode = "free-text",
  Multiple extends boolean = false,
>(
  options: AutocompleteQueryStateOptions & {
    mode?: Mode;
    multiple?: Multiple;
    queryOptions: (input: {
      search: string;
    }) => UseInfiniteQueryOptions<
      RawPage,
      ErrorType,
      InfiniteData<Page>,
      Key,
      Param
    >;
    getItems: (page: Page) => readonly Item[];
    getItemValue?: (item: NoInfer<Item>) => string;
    formatError?: (error: ErrorType) => ReactNode;
  }
) => {
  type Data = InfiniteData<Page>;
  const state = useAutocompleteQueryState(options);
  const getId = (item: Item) => {
    if (options.getItemValue) {
      return options.getItemValue(item);
    }
    if (typeof item === "string") {
      return item;
    }
    throw new Error("Object autocomplete items require getItemValue");
  };
  const native = options.queryOptions({ search: state.debouncedSearch });
  const nativeEnabled = native.enabled;
  const query = useInfiniteQuery({
    ...native,
    enabled: (q) =>
      state.eligible &&
      native.queryFn !== skipToken &&
      (typeof nativeEnabled === "function"
        ? nativeEnabled(q)
        : nativeEnabled !== false),
  });
  const generation = hashKey(native.queryKey);
  const guard = useRef({ generation, busy: false, failed: false });
  if (guard.current.generation !== generation) {
    guard.current = { generation, busy: false, failed: false };
  }
  const allowed = state.eligible && query.isEnabled;
  const usable =
    state.search === state.debouncedSearch &&
    !state.belowMinimum &&
    !query.isPlaceholderData;
  const pages =
    usable && query.data !== undefined
      ? (query.data as InfiniteData<SelectedPage<Data>>).pages
      : [];
  const items = dedupeAutocompleteItems(
    pages.flatMap((page) => [...options.getItems(page)]),
    getId
  );
  const load = async (retry: boolean) => {
    const operation = guard.current;
    if (
      !allowed ||
      !usable ||
      !query.hasNextPage ||
      query.isFetching ||
      operation.busy ||
      (!retry && (operation.failed || query.isFetchNextPageError))
    ) {
      return;
    }
    operation.busy = true;
    try {
      const result = await query.fetchNextPage({ cancelRefetch: false });
      operation.failed = result.isFetchNextPageError;
    } catch {
      operation.failed = true;
    } finally {
      operation.busy = false;
    }
  };
  const pagination: AutocompletePaginationProps = {
    hasNextPage: Boolean(query.hasNextPage),
    fetchingNextPage: query.isFetchingNextPage,
    disabled:
      !allowed || !usable || (query.isFetching && !query.isFetchingNextPage),
    error:
      query.isFetchNextPageError && query.error
        ? (options.formatError?.(query.error) ??
          "Could not load more suggestions.")
        : undefined,
    onLoadMore: () => load(false),
    onRetry: () => load(true),
  };
  const binding = {
    mode: options.mode ?? "free-text",
    multiple: options.multiple ?? false,
    items,
    filter: null,
    open: state.open,
    onOpenChange: state.setOpen,
    ...(options.mode !== "selection" && !options.multiple
      ? { value: state.search, onValueChange: state.setSearch }
      : { inputValue: state.search, onInputValueChange: state.setSearch }),
    hintMessage: state.belowMinimum ? state.hintMessage : undefined,
    loading:
      (state.open &&
        !state.belowMinimum &&
        state.search !== state.debouncedSearch) ||
      (allowed &&
        query.isFetching &&
        (query.data === undefined || query.isPlaceholderData)),
    backgroundLoading:
      usable &&
      query.data !== undefined &&
      query.isFetching &&
      !query.isFetchingNextPage,
    error:
      usable && query.data === undefined && query.error
        ? (options.formatError?.(query.error) ?? "Could not load suggestions.")
        : undefined,
    onRetry: () => {
      if (allowed) {
        return query.refetch();
      }
    },
    pagination,
  };
  return {
    query,
    pagination,
    search: state.search,
    open: state.open,
    setSearch: state.setSearch,
    setOpen: state.setOpen,
    autocompleteProps: binding as unknown as AutocompleteQueryBinding<
      Item,
      Mode,
      Multiple
    > &
      Pick<
        typeof binding,
        "hintMessage" | "backgroundLoading" | "onRetry" | "pagination"
      >,
  };
};
